import 'dart:async';

Stream<int> sonlar() async* {
  for (var i = 1; i <= 5; i++) {
    await Future<void>.delayed(const Duration(milliseconds: 10));
    yield i;
  }
}

Future<void> main() async {
  final natija = await sonlar()
      .asyncMap((x) async => x * 2)
      .where((x) => x % 4 == 0)
      .toList();
  print(natija);
}

import 'dart:async';

