import 'dart:async';

Future<void> main() async {
  final controller = StreamController<int>();
  final subscription = controller.stream.listen(
    (x) => print('event: $x'),
    onDone: () => print('yopildi'),
  );
  controller.add(1);
  subscription.pause();
  controller.add(2);
  print('pauza holati: ${subscription.isPaused}');
  subscription.resume();
  await Future<void>.delayed(const Duration(milliseconds: 10));
  controller.add(3);
  await controller.close();
  await Future<void>.delayed(const Duration(milliseconds: 10));
  print('yakun');
}

