import 'dart:async';
import 'package:flutter/material.dart';

void main() => runApp(const MaterialApp(home: Qiymatlar()));

class Qiymatlar extends StatefulWidget {
  const Qiymatlar({super.key});
  @override
  State<Qiymatlar> createState() => _QiymatlarState();
}

class _QiymatlarState extends State<Qiymatlar> {
  final Stream<int> _oqim = Stream<int>.delayed(
    const Duration(milliseconds: 100),
    () => 42,
  );
  bool _loglandi = false;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Center(
        child: StreamBuilder<int>(
          stream: _oqim,
          builder: (context, snapshot) {
            if (!snapshot.hasData) {
              return const Text('Yuklanmoqda...');
            }
            if (!_loglandi) {
              _loglandi = true;
              debugPrint('birinchi qiymat: ${snapshot.data}');
            }
            return Text('Qiymat: ${snapshot.data}');
          },
        ),
      ),
    );
  }
}

