import 'dart:async';

Future<void> main() async {
  final controller = StreamController<int>.broadcast();
  final a = controller.stream.listen((x) => print('A: $x'));
  final b = controller.stream.listen((x) => print('B: $x'));
  controller.add(1);
  await Future<void>.delayed(const Duration(milliseconds: 10));
  await a.cancel();
  controller.add(2);
  await Future<void>.delayed(const Duration(milliseconds: 10));
  await b.cancel();
  await controller.close();
  print('yakun');
}

